const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const body = items[i].json || {};
  const meta = $('Merge Videos').all()[i]?.json || {};
  for (const t of (body.items || [])) {
    const s = t.snippet?.topLevelComment?.snippet;
    if (!s) continue;
    out.push({ json: {
      query: meta.query || '',
      videoId: meta.videoId || '',
      videoTitle: meta.videoTitle || '',
      url: 'https://www.youtube.com/watch?v=' + (meta.videoId || '') + '&lc=' + (t.snippet.topLevelComment.id || ''),
      author: s.authorDisplayName || '',
      text: s.textDisplay || '',
      likeCount: s.likeCount || 0,
      publishedAt: s.publishedAt || '',
      replyCount: t.snippet.totalReplyCount || 0
    }});
  }
}
return out;

const cfg = $('Config').first().json;
const minLikes = Number(cfg.minLikes) || 0;
const rules = (cfg.ruleKeywords || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const out = [];
for (const item of $input.all()) {
  const t = (item.json.text || '').toLowerCase();
  const hit = (item.json.likeCount >= minLikes) && rules.some(r => t.includes(r));
  if (hit) out.push(item);
}
return out;

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const base = $('Rule Pre-filter').all()[i]?.json || {};
  let verdict = { match: false, category: 'other', reason: 'parse_error' };
  try {
    const txt = resp.candidates?.[0]?.content?.parts?.[0]?.text;
    if (txt) {
      const m = txt.match(/\{[\s\S]*\}/);
      if (m) verdict = JSON.parse(m[0]);
    }
  } catch (e) {}
  out.push({ json: { ...base, aiMatch: !!verdict.match, category: verdict.category || 'other', reason: verdict.reason || '' } });
}
return out;

// Each input item is one paginated Notion query API response.
// item.json.results is the array of Notion page objects for that batch.
// There is no separate URL property in this DB — the comment permalink
// lives as an href annotation on the Comment title's rich-text run.
const knownIds = [];
const seen = new Set();

for (const item of $input.all()) {
  const results = item.json.results || [];
  for (const page of results) {
    const runs = page.properties?.Comment?.title || [];
    const href = runs.find(r => r.href)?.href;
    if (href) {
      try {
        const lc = new URL(href).searchParams.get('lc');
        if (lc && !seen.has(lc)) {
          seen.add(lc);
          knownIds.push(lc);
        }
      } catch (e) {}
    }
  }
}

return [{ json: { knownIds } }];

// Items arriving here are from two branches merged by Sync Dedup:
//   - Comment items from Keep Matches: have .text, .url, .videoId, etc.
//   - One knownIds item from Extract Known IDs: has .knownIds (array of lc strings).
// Separate them by shape, build the known-id set, then drop already-stored comments.
const items = $input.all();

const knownIdsItem = items.find(i => Array.isArray(i.json.knownIds));
const commentItems = items.filter(i => !Array.isArray(i.json.knownIds));

const knownIds = new Set(knownIdsItem?.json?.knownIds || []);

const out = [];
for (const item of commentItems) {
  const url = item.json.url || '';
  let lc = '';
  try { lc = new URL(url).searchParams.get('lc') || ''; } catch (e) {}
  // If lc can't be parsed (safety), let it through.
  if (!lc || !knownIds.has(lc)) {
    out.push(item);
  }
}
return out;
